#include <stdio.h>
#include <stdlib.h>

int main() {
    int *arr = calloc(1000000000000, sizeof(int));
    if (arr == NULL) {
        printf("Allocation failed\n");
        return 1;
    }
    arr[0] = 1;
    printf("%d\n", arr[0]);
    free(arr);
    return 0;
}
